'use strict';

// MODULES //

var tape = require( 'tape' );
var Float64Array = require( '@stdlib/array/float64' );
var scalar2ndarray = require( '@stdlib/ndarray/from-scalar' );
var ndarray = require( '@stdlib/ndarray/base/ctor' );
var getData = require( '@stdlib/ndarray/data-buffer' );
var dapxsum = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof dapxsum, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function adds a scalar constant to each element and computes the sum', function test( t ) {
	var alpha;
	var xbuf;
	var x;
	var v;

	xbuf = new Float64Array( [ 1.0, -2.0, 2.0 ] );
	x = ndarray( 'float64', xbuf, [ 3 ], [ 1 ], 0, 'row-major' );
	alpha = scalar2ndarray( 5.0, {
		'dtype': 'float64'
	});

	v = dapxsum( [ x, alpha ] );

	t.strictEqual( v, 16.0, 'returns expected value' );
	t.deepEqual( getData( x ), new Float64Array( [ 1.0, -2.0, 2.0 ] ), 'returns expected value' );
	t.end();
});

tape( 'the function supports one-dimensional ndarrays having non-unit strides', function test( t ) {
	var alpha;
	var xbuf;
	var x;
	var v;

	xbuf = new Float64Array( [ 1.0, 99, -2.0, 99, 2.0 ] );
	x = ndarray( 'float64', xbuf, [ 3 ], [ 2 ], 0, 'row-major' );
	alpha = scalar2ndarray( 5.0, {
		'dtype': 'float64'
	});

	v = dapxsum( [ x, alpha ] );

	t.strictEqual( v, 16.0, 'returns expected value' );
	t.end();
});

tape( 'the function supports one-dimensional ndarrays having non-zero offsets', function test( t ) {
	var alpha;
	var xbuf;
	var x;
	var v;

	xbuf = new Float64Array( [ 99, 1.0, -2.0, 2.0 ] );
	x = ndarray( 'float64', xbuf, [ 3 ], [ 1 ], 1, 'row-major' );
	alpha = scalar2ndarray( 5.0, {
		'dtype': 'float64'
	});

	v = dapxsum( [ x, alpha ] );

	t.strictEqual( v, 16.0, 'returns expected value' );
	t.end();
});

tape( 'the function supports one-dimensional ndarrays having negative strides', function test( t ) {
	var alpha;
	var xbuf;
	var x;
	var v;

	xbuf = new Float64Array( [ 1.0, -2.0, 2.0 ] );
	x = ndarray( 'float64', xbuf, [ 3 ], [ -1 ], 2, 'row-major' );
	alpha = scalar2ndarray( 5.0, {
		'dtype': 'float64'
	});

	v = dapxsum( [ x, alpha ] );

	t.strictEqual( v, 16.0, 'returns expected value' );
	t.end();
});

tape( 'the function returns 0.0 for a one-dimensional empty ndarray', function test( t ) {
	var alpha;
	var xbuf;
	var x;
	var v;

	xbuf = new Float64Array( [] );
	x = ndarray( 'float64', xbuf, [ 0 ], [ 1 ], 0, 'row-major' );
	alpha = scalar2ndarray( 5.0, {
		'dtype': 'float64'
	});

	v = dapxsum( [ x, alpha ] );

	t.strictEqual( v, 0.0, 'returns expected value' );
	t.end();
});
